package main

import (
	"bytes"

	"github.com/phpdave11/gofpdf"
)

// Practical steps for constructing and reading stereograms.
func makeGuidePDF() ([]byte, error) {
	p := gofpdf.New("P", "mm", "A4", "")
	p.SetMargins(15, 12, 15)
	p.SetAutoPageBreak(false, 0)
	font, _ := resources.ReadFile("assets/DejaVuSans.ttf")
	p.AddUTF8FontFromBytes("DV", "", font)
	p.SetTitle("Как выполнять построения на сетке Вульфа", true)
	p.SetAuthor("Сетка Вульфа · учебная памятка", true)
	y := 0.
	page := func(title string, n int) {
		p.AddPage()
		textAt(p, 15, 15, title, 15)
		wrapped(p, 15, 21, 180, "Пошаговая памятка: построение по исходным данным и определение элементов по готовой стереограмме.", 8)
		textAt(p, 15, 290, "Сетка Вульфа · равноугольная проекция · нижняя полусфера", 7)
		textAt(p, 162, 290, "Памятка · "+string(rune('0'+n))+"/2", 7)
		y = 36
	}
	section := func(title, body string) {
		textAt(p, 15, y, title, 10)
		y += 3
		setFont(p, 9.5)
		p.SetXY(15, y)
		p.MultiCell(180, 5, body, "", "L", false)
		y = p.GetY() + 7
	}
	page("Построения: от условия к стереограмме", 1)
	section("1. Подготовьте кальку", "Наложите кальку на распечатанную сетку и совместите центры. Обведите внешний круг, отметьте север (0°), восток (90°), юг (180°), запад (270°). Сетка остаётся неподвижной; вращайте кальку вокруг центра. После каждого построения возвращайте север кальки к 0°. Все элементы варианта наносите на одну и ту же кальку.")
	section("2. Плоскость P: дуга большого круга", "Дано: азимут падения и угол падения. На внешнем круге отметьте азимут падения. Поверните кальку так, чтобы эта отметка попала на горизонтальный диаметр справа или слева. От внешнего круга к центру отложите угол падения. Через найденное место обведите соответствующую дугу большого круга. Верните кальку в исходное положение и подпишите P.")
	section("3. Линейность L: точка", "Дано: азимут погружения и угол погружения. Отметьте азимут на внешнем круге и совместите его с горизонтальным или вертикальным диаметром. От внешнего круга к центру отсчитайте угол погружения и поставьте точку L. Верните север к 0°. Для линии результатом является точка, для плоскости — дуга.")
	section("4. Линейность Lr в плоскости R: склонение (rake)", "Сначала постройте плоскость R по её азимуту и углу падения. Условие rake задаёт угол в этой плоскости между Lr и линией простирания. Указан конец отсчёта, например «25° от СЗ (аз. 308°)» для плоскости 38°/40°. Совместите дугу R с большим кругом сетки. От указанного конца простирания отложите rake ВДОЛЬ ЭТОЙ ДУГИ внутрь полусферы и отметьте точку Lr. Верните север к 0°; определите азимут и угол погружения Lr.")
	section("5. Полюс плоскости Np", "Полюс — проекция перпендикуляра к плоскости. Совместите дугу P с большим кругом сетки и от её пересечения с горизонтальным диаметром отсчитайте по диаметру 90° в сторону противоположного направления падения. Поставьте точку Np и верните кальку в исходное положение. Определение полюса одинаково для сеток Вульфа и Шмидта.")
	page("Складка и чтение готовой стереограммы", 2)
	section("6. Крылья K1 и K2, шарнир H", "Постройте обе плоскости как дуги большого круга. Точка их пересечения — проекция шарнира H. Поверните кальку, чтобы H оказался на диаметре; от внешнего круга до H считайте угол погружения. Верните север к 0° и считайте азимут погружения. В задании требуется записать ОБА значения шарнира.")
	section("7. π-плоскость, угол крыльев и осевая поверхность", "Постройте плоскость, перпендикулярную шарниру: H является её полюсом. Это π-плоскость. Обозначьте A и B её пересечения с K1 и K2. Совместите π-плоскость с большим кругом сетки и измерьте дугу AB: углы между крыльями составляют α и 180° − α. Разделите пополам оба соответствующих угловых сектора; через каждую биссектрису и шарнир постройте вариант осевой поверхности — ОП1 или ОП2. Без сведений о взаимном положении и полярности крыльев выбор неоднозначен: в работе запишите оба варианта.")
	section("8. Обратная задача: от готовых дуг и точек к значениям", "На втором листе нанесён другой случайный набор. Для P и R совместите дугу с большим кругом, определите угол падения и верните север к 0°, чтобы считать азимут падения. Для L и Lr совместите точку с диаметром, отсчитайте погружение ОТ ВНЕШНЕГО КРУГА; после возврата кальки считайте азимут. Для rake совместите R с большим кругом и отсчитайте угол вдоль него от ближайшего конца простирания до Lr. Запишите также, от какого конца шёл отсчёт: направление и его азимут. Для K1/K2 повторите построения шарнира и π-плоскости из пунктов 6–7.")
	section("9. Как читать обозначения и ответы", "P — отдельная плоскость; Np — её полюс; L — отдельная линейность. R — плоскость для rake; Lr — линейность в ней. K1 и K2 — крылья; H — шарнир; π — плоскость, перпендикулярная H; A/B — её пересечения с крыльями. ОП1/ОП2 — два варианта осевой поверхности. В ответах «азимут/угол»: для плоскости это падение, для линии — погружение. Не принимайте азимут простирания за азимут падения.")
	section("10. Проверка результата и печать", "Крутая линия располагается ближе к центру, пологая — ближе к внешнему кругу. Lr должен лежать на дуге R, H — на обеих дугах крыльев. Угол rake отсчитывается по дуге плоскости, угол погружения — по диаметру. Печатайте задания на A4 в масштабе 100%: диаметр сетки 180 мм. Расчётные ответы округлены до 0,1°; для ручного считывания ориентир допуска ±2° (окончательный допуск задаёт преподаватель).")
	var b bytes.Buffer
	err := p.Output(&b)
	return b.Bytes(), err
}
